css:
.tqt-backtest-tearsheet{--tq-bg:#0B0E14;--tq-ln:#1A2130;--tq-tx:#C8D2E0;--tq-mu:#6B7A90;--tq-am:#F0A93B;--tq-up:#2ED47A;--tq-dn:#FF4D5E;--tq-cy:#4CC9E0;width:100%;background:var(--tq-bg);border:1px solid var(--tq-ln);color:var(--tq-tx);font-family:ui-monospace,Menlo,Consolas,monospace;font-size:9px;line-height:1.3;font-variant-numeric:tabular-nums}
.tqt-backtest-tearsheet *{box-sizing:border-box}
.tqt-backtest-tearsheet-hd{display:flex;justify-content:space-between;align-items:baseline;gap:6px;padding:4px 6px;border-bottom:1px solid var(--tq-ln);background:#0E1219}
.tqt-backtest-tearsheet-hd b{font-weight:600;font-size:9.5px;letter-spacing:.05em;color:var(--tq-am)}
.tqt-backtest-tearsheet-hd span{font-size:7.5px;color:var(--tq-mu)}
.tqt-backtest-tearsheet-tabs{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--tq-ln)}
.tqt-backtest-tearsheet-t{all:unset;box-sizing:border-box;cursor:pointer;text-align:center;padding:3px 0;font-family:inherit;font-size:8px;letter-spacing:.12em;color:var(--tq-mu);border-right:1px solid var(--tq-ln)}
.tqt-backtest-tearsheet-t:last-child{border-right:0}
.tqt-backtest-tearsheet-t:hover{color:var(--tq-tx)}
.tqt-backtest-tearsheet-t[aria-selected="true"]{background:#16202E;color:var(--tq-am)}
.tqt-backtest-tearsheet-t:focus-visible{outline:1px solid var(--tq-cy);outline-offset:-1px}
.tqt-backtest-tearsheet-plot{padding:5px 6px 4px;border-bottom:1px solid var(--tq-ln)}
.tqt-backtest-tearsheet-svg{display:block;width:100%;height:62px}
.tqt-backtest-tearsheet-uw{display:block;width:100%;height:16px;margin-top:1px}
.tqt-backtest-tearsheet-gl{stroke:#141A25;stroke-width:1;vector-effect:non-scaling-stroke}
.tqt-backtest-tearsheet-eq{fill:none;stroke:var(--tq-am);stroke-width:1.3;vector-effect:non-scaling-stroke;stroke-linejoin:round;stroke-dasharray:1;animation:tqt-backtest-tearsheet-draw .85s ease-out}
.tqt-backtest-tearsheet-bm{fill:none;stroke:#42536B;stroke-width:1;vector-effect:non-scaling-stroke;stroke-dasharray:3 2}
.tqt-backtest-tearsheet-dd{fill:rgba(255,77,94,.28);stroke:var(--tq-dn);stroke-width:.8;vector-effect:non-scaling-stroke}
.tqt-backtest-tearsheet-lg{display:flex;align-items:center;gap:4px;margin-top:3px;font-size:7px;letter-spacing:.08em;color:var(--tq-mu)}
.tqt-backtest-tearsheet-lg i{width:8px;height:2px;display:inline-block}
.tqt-backtest-tearsheet-k1{background:var(--tq-am)}
.tqt-backtest-tearsheet-k2{background:#42536B;margin-left:5px}
.tqt-backtest-tearsheet-rg{margin-left:auto;color:#54637A}
.tqt-backtest-tearsheet-stats{display:grid;grid-template-columns:repeat(4,1fr)}
.tqt-backtest-tearsheet-c{padding:3px 5px 3px 4px;border-right:1px solid var(--tq-ln);border-bottom:1px solid var(--tq-ln);min-width:0;overflow:hidden}
.tqt-backtest-tearsheet-c:nth-child(4n){border-right:0}
.tqt-backtest-tearsheet-l{display:block;font-size:6.5px;letter-spacing:.07em;color:var(--tq-mu);white-space:nowrap}
.tqt-backtest-tearsheet-v{display:block;font-size:10px;text-align:right;white-space:nowrap}
.tqt-backtest-tearsheet-up{color:var(--tq-up)}
.tqt-backtest-tearsheet-dn{color:var(--tq-dn)}
.tqt-backtest-tearsheet-am{color:var(--tq-am)}
.tqt-backtest-tearsheet-ft{display:flex;justify-content:space-between;gap:6px;padding:3px 6px;font-size:7.5px;color:var(--tq-mu)}
.tqt-backtest-tearsheet-ft b{font-weight:400;color:var(--tq-tx)}
@keyframes tqt-backtest-tearsheet-draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
@media (prefers-reduced-motion:reduce){.tqt-backtest-tearsheet-eq{animation:none}}

