var R=(function(s){return function(){s=s+0x6D2B79F5|0;var t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};})(20240617);
function gz(){var u=1-R(),v=R();return Math.sqrt(-2*Math.log(u))*Math.cos(6.2831853*v);}
var N=1512,sr=[],br=[],i;
for(i=0;i<N;i++){var m=0.00028+0.0089*gz();var e=0.00021+0.0053*gz();br.push(m);sr.push(0.85*m+e-0.0000079);}
var WIN=[['1Y',252,'2023-07 → 2024-06'],['3Y',756,'2021-07 → 2024-06'],['5Y',1260,'2019-07 → 2024-06'],['ITD',1512,'2018-07 → 2024-06']];
function eqc(a,f,t){var e=[1],v=1;for(var k=f;k<t;k++){v*=1+a[k];e.push(v);}return e;}
function stat(f,t){var n=t-f,es=eqc(sr,f,t),eb=eqc(br,f,t),k;
 var cg=Math.pow(es[n],252/n)-1,cb=Math.pow(eb[n],252/n)-1,mu=0,mb=0;
 for(k=f;k<t;k++){mu+=sr[k];mb+=br[k];}mu/=n;mb/=n;
 var vr=0,dn=0,cov=0,vb=0,dm=0;
 for(k=f;k<t;k++){var d=sr[k]-mu;vr+=d*d;if(sr[k]<0)dn+=sr[k]*sr[k];cov+=d*(br[k]-mb);vb+=(br[k]-mb)*(br[k]-mb);dm+=sr[k]-br[k];}
 dm/=n;var dv=0;for(k=f;k<t;k++){var q=(sr[k]-br[k])-dm;dv+=q*q;}
 var vol=Math.sqrt(vr/(n-1)*252),dvol=Math.sqrt(dn/n*252),te=Math.sqrt(dv/(n-1)*252),be=cov/vb;
 var pk=1,mdd=0,hwm=1,dd=[0];
 for(k=1;k<=n;k++){if(es[k]>pk)pk=es[k];if(es[k]>hwm)hwm=es[k];var x=es[k]/pk-1;dd.push(x);if(x<mdd)mdd=x;}
 var hit=0;for(k=f;k<t;k++)if(sr[k]>0)hit++;
 var sl=sr.slice(f,t).sort(function(x,y){return x-y;});
 var rf=0.02;
 return{cg:cg,vol:vol,shp:(cg-rf)/vol,srt:(cg-rf)/dvol,mdd:mdd,cal:cg/Math.abs(mdd),hit:hit/n,
  best:sl[n-1],worst:sl[0],be:be,al:cg-(rf+be*(cb-rf)),te:te,ir:(cg-cb)/te,vr95:sl[Math.floor(n*0.05)],
  es:es,eb:eb,dd:dd,nav:es[n],hwm:hwm};}
function samp(a,k){var o=[],n=a.length-1;for(var j=0;j<=k;j++)o.push(a[Math.round(j/k*n)]);return o;}
function pth(a,w,h,lo,hi){var s='',n=a.length-1;for(var j=0;j<=n;j++){var x=j/n*w,y=h-(a[j]-lo)/(hi-lo)*h;s+=(j?'L':'M')+x.toFixed(1)+' '+y.toFixed(1);}return s;}
function pc(x,d){return(x>=0?'+':'')+(x*100).toFixed(d)+'%';}
var tabs=root.querySelector('.tqt-backtest-tearsheet-tabs'),grid=root.querySelector('.tqt-backtest-tearsheet-stats');
var pe=root.querySelector('.tqt-backtest-tearsheet-eq'),pb=root.querySelector('.tqt-backtest-tearsheet-bm'),pd=root.querySelector('.tqt-backtest-tearsheet-dd');
var cur=2;
WIN.forEach(function(w,ix){var b=document.createElement('button');b.type='button';b.className='tqt-backtest-tearsheet-t';b.textContent=w[0];b.setAttribute('role','tab');b.setAttribute('aria-selected',ix===cur?'true':'false');
 b.addEventListener('click',function(){draw(ix);});
 b.addEventListener('keydown',function(ev){var d=ev.key==='ArrowRight'?1:ev.key==='ArrowLeft'?-1:0;if(!d)return;ev.preventDefault();var nx=(ix+d+WIN.length)%WIN.length;draw(nx);tabs.children[nx].focus();});
 tabs.appendChild(b);});
function draw(ix){cur=ix;var w=WIN[ix],s=stat(N-w[1],N);
 for(var j=0;j<tabs.children.length;j++)tabs.children[j].setAttribute('aria-selected',j===ix?'true':'false');
 var a=samp(s.es,200),b=samp(s.eb,200),lo=Math.min(Math.min.apply(null,a),Math.min.apply(null,b)),hi=Math.max(Math.max.apply(null,a),Math.max.apply(null,b));
 var pad=(hi-lo)*0.08;lo-=pad;hi+=pad;
 pe.setAttribute('d',pth(a,300,62,lo,hi));pb.setAttribute('d',pth(b,300,62,lo,hi));
 var dd=samp(s.dd,200),md=Math.min.apply(null,dd)||-0.01;
 pd.setAttribute('d',pth(dd,300,16,md,0)+'L300 0L0 0Z');
 pe.style.animation='none';void root.offsetHeight;pe.style.animation='';
 root.querySelector('.tqt-backtest-tearsheet-rg').textContent=w[2]+' · n='+w[1];
 root.querySelector('.tqt-backtest-tearsheet-nav').textContent=(s.nav*100).toFixed(1);
 root.querySelector('.tqt-backtest-tearsheet-hwm').textContent=(s.hwm*100).toFixed(1);
 var C=[['CAGR',pc(s.cg,2),s.cg>=0?'up':'dn'],['ANN VOL',(s.vol*100).toFixed(1)+'%',''],['SHARPE',s.shp.toFixed(2),s.shp>=1?'up':'am'],['SORTINO',s.srt.toFixed(2),''],
  ['MAX DD',pc(s.mdd,2),'dn'],['CALMAR',s.cal.toFixed(2),''],['HIT RATE',(s.hit*100).toFixed(1)+'%',''],['VaR95 1D',pc(s.vr95,2),'dn'],
  ['BEST DAY',pc(s.best,2),'up'],['WORST DAY',pc(s.worst,2),'dn'],['BETA SPX',s.be.toFixed(2),''],['ALPHA',pc(s.al,2),s.al>=0?'up':'dn'],
  ['TRK ERR',(s.te*100).toFixed(2)+'%',''],['INFO RATIO',(s.ir>=0?'+':'')+s.ir.toFixed(2),s.ir>=0?'up':'dn'],['TURNOVER','186%',''],['EXPOSURE','0.97x','']];
 grid.innerHTML='';
 C.forEach(function(c){var d=document.createElement('div');d.className='tqt-backtest-tearsheet-c';
  var l=document.createElement('span');l.className='tqt-backtest-tearsheet-l';l.textContent=c[0];
  var v=document.createElement('span');v.className='tqt-backtest-tearsheet-v'+(c[2]?' tqt-backtest-tearsheet-'+c[2]:'');v.textContent=c[1];
  d.appendChild(l);d.appendChild(v);grid.appendChild(d);});}
draw(cur);

css:
.tqt-factor-tstats{--tq-bg:#0B0E14;--tq-ln:#1A2130;--tq-tx:#C8D2E0;--tq-mu:#6B7A90;--tq-am:#F0A93B;--tq-up:#2ED47A;--tq-dn:#FF4D5E;--tq-cy:#4CC9E0;width:100%;background:var(--tq-bg);border:1px solid var(--tq-ln);color:var(--tq-tx);font-family:ui-monospace,Menlo,Consolas,monospace;font-size:9px;line-height:1.25;font-variant-numeric:tabular-nums}
.tqt-factor-tstats *{box-sizing:border-box}
.tqt-factor-tstats-hd{display:flex;justify-content:space-between;align-items:baseline;gap:6px;padding:4px 6px;border-bottom:1px solid var(--tq-ln);background:#0E1219}
.tqt-factor-tstats-hd b{font-weight:600;font-size:9.5px;letter-spacing:.06em;color:var(--tq-am)}
.tqt-factor-tstats-hd span{font-size:7.5px;color:var(--tq-mu)}
.tqt-factor-tstats-cols,.tqt-factor-tstats-r{display:grid;grid-template-columns:44px 28px 1fr 1fr .9fr 1.15fr;gap:2px;padding:2px 6px;align-items:center}
.tqt-factor-tstats-cols{font-size:6.5px;letter-spacing:.08em;color:var(--tq-mu);border-bottom:1px solid var(--tq-ln)}
.tqt-factor-tstats-cols span:nth-child(n+3){text-align:right}
.tqt-factor-tstats-rows{border-bottom:1px solid var(--tq-ln)}
.tqt-factor-tstats-rows:focus-visible{outline:1px solid var(--tq-cy);outline-offset:-1px}
.tqt-factor-tstats-r{cursor:pointer;border-bottom:1px solid #11161F}
.tqt-factor-tstats-r:hover{background:#111722}
.tqt-factor-tstats-r[aria-selected="true"]{background:#16202E}
.tqt-factor-tstats-r[aria-selected="true"] .tqt-factor-tstats-n{color:var(--tq-am)}
.tqt-factor-tstats-n{font-size:8.5px;letter-spacing:.03em;white-space:nowrap;overflow:hidden}
.tqt-factor-tstats-num{text-align:right;font-size:8.5px;white-space:nowrap}
.tqt-factor-tstats-bar{position:relative;height:7px;background:#10151E}
.tqt-factor-tstats-bar::after{content:"";position:absolute;left:50%;top:0;bottom:0;width:1px;background:#2A3446}
.tqt-factor-tstats-fill{position:absolute;top:1px;bottom:1px;background:var(--tq-cy)}
.tqt-factor-tstats-up{color:var(--tq-up)}
.tqt-factor-tstats-dn{color:var(--tq-dn)}
.tqt-factor-tstats-ns{color:var(--tq-mu)}
.tqt-factor-tstats-sig{font-size:6px;color:var(--tq-am);margin-left:2px}
.tqt-factor-tstats-nsm{font-size:6px;color:var(--tq-mu);margin-left:2px}
.tqt-factor-tstats-tot{background:#0E141D;border-top:1px solid var(--tq-ln);border-bottom:0}
.tqt-factor-tstats-tot .tqt-factor-tstats-n{color:var(--tq-am)}
.tqt-factor-tstats-dtl{padding:3px 6px;font-size:7.5px;color:var(--tq-mu);border-bottom:1px solid var(--tq-ln);min-height:26px;transition:background .18s ease}
.tqt-factor-tstats-dtl b{font-weight:400;color:var(--tq-tx)}
.tqt-factor-tstats-ft{display:flex;justify-content:space-between;gap:4px;padding:3px 6px;font-size:7px;color:var(--tq-mu)}
.tqt-factor-tstats-ft b{font-weight:400;color:var(--tq-tx)}
@media (prefers-reduced-motion:reduce){.tqt-factor-tstats-dtl{transition:none}}

