var F=[['MKT-RF',0.94,0.041,5.80,'MSCI World excess of 1M bill'],['SMB',-0.21,0.062,1.90,'small minus big, cap-wtd'],['HML',0.38,0.058,2.40,'book/price, sector-neutral'],['UMD',0.55,0.090,4.15,'12M-1M price momentum'],['RMW',0.12,0.071,2.05,'gross profitability robust-weak'],['CMA',-0.07,0.083,1.60,'asset growth cons-aggr'],['BAB',0.19,0.066,3.10,'betting against beta, lev-adj']];
var AL=[0.0218,0.0094,'annualised intercept, net of fees'];
function cdf(z){var t=1/(1+0.2316419*Math.abs(z));var d=0.3989423*Math.exp(-z*z/2);var p=d*t*(1.330274*t*t*t*t-1.821256*t*t*t+1.781478*t*t-0.356538*t+0.319381);return z>0?1-p:p;}
function pv(t){return 2*(1-cdf(Math.abs(t)));}
function star(t){var a=Math.abs(t);return a>=2.576?'***':a>=1.96?'**':a>=1.645?'*':'ns';}
function bp(x){return(x>=0?'+':'−')+Math.abs(Math.round(x*10000))+'bp';}
var rows=root.querySelector('.tqt-factor-tstats-rows'),dtl=root.querySelector('.tqt-factor-tstats-dtl');
var D=[],tot=0,i;
for(i=0;i<F.length;i++){var c=F[i][1]*F[i][3]/100;tot+=c;D.push({n:F[i][0],b:F[i][1],se:F[i][2],t:F[i][1]/F[i][2],c:c,d:F[i][4]+' · prem '+F[i][3].toFixed(2)+'%/yr'});}
tot+=AL[0];
D.push({n:'ALPHA',b:null,se:AL[1],t:AL[0]/AL[1],c:AL[0],d:AL[2]});
var sel=3;
D.forEach(function(r,ix){var e=document.createElement('div');e.className='tqt-factor-tstats-r';e.setAttribute('role','option');e.setAttribute('aria-selected',ix===sel?'true':'false');
 var st=star(r.t),cl=r.t>=0?'up':'dn';if(st==='ns')cl='ns';
 var bar='<span class="tqt-factor-tstats-bar"></span>';
 e.innerHTML='<span class="tqt-factor-tstats-n"></span>'+bar+'<span class="tqt-factor-tstats-num"></span><span class="tqt-factor-tstats-num tqt-factor-tstats-ns"></span><span class="tqt-factor-tstats-num tqt-factor-tstats-'+cl+'"></span><span class="tqt-factor-tstats-num tqt-factor-tstats-'+(r.c>=0?'up':'dn')+'"></span>';
 e.children[0].textContent=r.n;
 if(r.b!==null){var f=document.createElement('span');f.className='tqt-factor-tstats-fill';var w=Math.min(Math.abs(r.b),1)*50;
  if(r.b>=0){f.style.left='50%';f.style.width=w+'%';}else{f.style.right='50%';f.style.width=w+'%';}
  e.children[1].appendChild(f);}
 e.children[2].textContent=r.b===null?(r.c*100).toFixed(2)+'%':(r.b>=0?'+':'−')+Math.abs(r.b).toFixed(2);
 e.children[3].textContent=r.se.toFixed(r.b===null?4:3);
 e.children[4].innerHTML=(r.t>=0?'+':'−')+Math.abs(r.t).toFixed(2)+'<i class="tqt-factor-tstats-'+(st==='ns'?'nsm':'sig')+'">'+st+'</i>';
 e.children[5].textContent=bp(r.c);
 e.addEventListener('click',function(){pick(ix);});
 rows.appendChild(e);});
var tr=document.createElement('div');tr.className='tqt-factor-tstats-r tqt-factor-tstats-tot';
tr.innerHTML='<span class="tqt-factor-tstats-n">TOTAL</span><span></span><span class="tqt-factor-tstats-num tqt-factor-tstats-ns">Σβ·prem</span><span></span><span></span><span class="tqt-factor-tstats-num tqt-factor-tstats-up"></span>';
tr.children[5].textContent=bp(tot);
rows.appendChild(tr);
function pick(ix){sel=ix;
 for(var j=0;j<D.length;j++)rows.children[j].setAttribute('aria-selected',j===ix?'true':'false');
 var r=D[ix],p=pv(r.t);
 dtl.innerHTML='<b>'+r.n+'</b> β '+(r.b===null?'—':(r.b>=0?'+':'−')+Math.abs(r.b).toFixed(2))+' ±'+r.se.toFixed(3)+' · t <b>'+(r.t>=0?'+':'−')+Math.abs(r.t).toFixed(2)+'</b> '+star(r.t)+' · p '+(p<0.001?'&lt;0.001':p.toFixed(3))+' · contr <b>'+bp(r.c)+'</b><br>'+r.d;}
rows.addEventListener('keydown',function(ev){var d=ev.key==='ArrowDown'?1:ev.key==='ArrowUp'?-1:0;if(!d)return;ev.preventDefault();pick((sel+d+D.length)%D.length);});
pick(sel);

css:
.tqt-corr-matrix{--tq-bg:#0B0E14;--tq-ln:#1A2130;--tq-tx:#C8D2E0;--tq-mu:#6B7A90;--tq-am:#F0A93B;--tq-cy:#4CC9E0;width:100%;background:var(--tq-bg);border:1px solid var(--tq-ln);color:var(--tq-tx);font-family:ui-monospace,Menlo,Consolas,monospace;font-size:9px;line-height:1.2;font-variant-numeric:tabular-nums}
.tqt-corr-matrix *{box-sizing:border-box}
.tqt-corr-matrix-hd{display:flex;justify-content:space-between;align-items:baseline;gap:6px;padding:4px 6px;border-bottom:1px solid var(--tq-ln);background:#0E1219}
.tqt-corr-matrix-hd b{font-weight:600;font-size:9.5px;letter-spacing:.06em;color:var(--tq-am)}
.tqt-corr-matrix-hd span{font-size:7.5px;color:var(--tq-mu)}
.tqt-corr-matrix-grid{display:grid;grid-template-columns:30px repeat(8,1fr);gap:1px;padding:5px 6px;background:transparent}
.tqt-corr-matrix-h{font-size:6.5px;letter-spacing:.02em;color:var(--tq-mu);text-align:center;padding:1px 0;overflow:hidden}
.tqt-corr-matrix-rh{font-size:6.5px;color:var(--tq-mu);text-align:left;display:flex;align-items:center}
.tqt-corr-matrix-on{color:var(--tq-am)}
.tqt-corr-matrix-c{height:16px;display:flex;align-items:center;justify-content:center;font-size:7.5px;background:#10151E;color:#8895A8;cursor:crosshair}
.tqt-corr-matrix-c:focus{outline:1px solid var(--tq-cy);outline-offset:-1px}
.tqt-corr-matrix-hi{color:#FFF2E0}
.tqt-corr-matrix-d{background:#233042;color:var(--tq-am)}
.tqt-corr-matrix-mk{box-shadow:inset 0 0 0 1px var(--tq-am)}
.tqt-corr-matrix-rd{padding:3px 6px;font-size:8px;color:var(--tq-mu);border-top:1px solid var(--tq-ln);border-bottom:1px solid var(--tq-ln);white-space:nowrap;overflow:hidden}
.tqt-corr-matrix-rd b{font-weight:400;color:var(--tq-tx)}
.tqt-corr-matrix-ft{display:flex;justify-content:space-between;align-items:center;gap:6px;padding:3px 6px;font-size:6.5px;color:var(--tq-mu)}
.tqt-corr-matrix-scale{display:flex;align-items:center;gap:2px}
.tqt-corr-matrix-scale i{width:11px;height:6px;display:inline-block}
.tqt-corr-matrix-s1{background:rgba(76,201,224,.85)}
.tqt-corr-matrix-s2{background:rgba(76,201,224,.38)}
.tqt-corr-matrix-s3{background:#10151E}
.tqt-corr-matrix-s4{background:rgba(255,90,80,.38)}
.tqt-corr-matrix-s5{background:rgba(255,90,80,.85)}
@media (prefers-reduced-motion:reduce){.tqt-corr-matrix-c{transition:none}}

