var A=['SPX','NDX','RTY','TLT','HYG','GLD','DXY','CL1'];
var T=[[.93,.86,-.32,.74,.11,-.28,.34],[.78,-.24,.66,.17,-.31,.22],[-.35,.71,.08,-.30,.38],[.18,.41,-.19,-.21],[.19,-.35,.40],[-.52,.26],[-.24]];
