var V=[['const',0.0021,0.00090,1.21],['CARRY',0.4180,0.07310,1.42],['MOM3M',0.2634,0.08120,1.31],['VALUE',-0.1187,0.06690,1.55],['INVGRD',0.0942,0.04100,1.27]];
var VIF=[0,1.34,1.61,1.28,1.19],N=120,K=4,DFR=N-K-1;
function cdf(z){var t=1/(1+0.2316419*Math.abs(z)),d=0.3989423*Math.exp(-z*z/2);var p=d*t*(1.330274*t*t*t*t-1.821256*t*t*t+1.781478*t*t-0.356538*t+0.319381);return z>0?1-p:p;}
function pv(t){return 2*(1-cdf(Math.abs(t)));}
function chiP(x){return Math.exp(-x/2)*(1+x/2);}
function ex(p){return p<0.0005?p.toExponential(1).replace('e-','e−'):p.toFixed(3);}
var chi0=0,i;
for(i=1;i<V.length;i++){var t0=V[i][1]/V[i][2];chi0+=t0*t0;}
var R2=chi0/(chi0+DFR),AR2=1-(1-R2)*(N-1)/DFR;
var est=0,sel=1;
var rows=root.querySelector('.tqt-ols-summary-rows'),meta=root.querySelector('.tqt-ols-summary-meta');
var ci=root.querySelector('.tqt-ols-summary-ci'),diag=root.querySelector('.tqt-ols-summary-diag');
var btns=root.querySelectorAll('.tqt-ols-summary-b');
for(i=0;i<btns.length;i++)(function(b){b.addEventListener('click',function(){est=+b.getAttribute('data-e');render();});})(btns[i]);
V.forEach(function(v,ix){var e=document.createElement('div');e.className='tqt-ols-summary-r';e.setAttribute('role','option');
 e.innerHTML='<span></span><span></span><span></span><span></span><span></span>';
 e.addEventListener('click',function(){sel=ix;render();});rows.appendChild(e);});
rows.addEventListener('keydown',function(ev){var d=ev.key==='ArrowDown'?1:ev.key==='ArrowUp'?-1:0;if(!d)return;ev.preventDefault();sel=(sel+d+V.length)%V.length;render();});
function se(ix){return V[ix][2]*(est?V[ix][3]:1);}
function render(){var chi=0,k;
 for(k=0;k<btns.length;k++)btns[k].setAttribute('aria-pressed',k===est?'true':'false');
 for(k=1;k<V.length;k++){var tt=V[k][1]/se(k);chi+=tt*tt;}
 meta.innerHTML='';
 var pairs=[['Dep. Variable','XSRET_HG1M'],['R-squared',R2.toFixed(3)],['No. Observations',String(N)],['Adj. R-squared',AR2.toFixed(3)],['Df Residuals',String(DFR)],['Wald χ²(4)',chi.toFixed(1)],['Cov. estimator',est?'HAC · NW(6)':'nonrobust'],['Prob &gt; χ²',ex(chiP(chi))]];
 pairs.forEach(function(p){var a=document.createElement('span');a.innerHTML=p[0];var b=document.createElement('span');b.innerHTML=p[1];meta.appendChild(a);meta.appendChild(b);});
 for(k=0;k<V.length;k++){var r=rows.children[k],s=se(k),t=V[k][1]/s,p=pv(t);
  r.setAttribute('aria-selected',k===sel?'true':'false');
  r.children[0].textContent=V[k][0];
  r.children[1].textContent=(V[k][1]>=0?' ':'−')+Math.abs(V[k][1]).toFixed(4);
  r.children[2].textContent=s.toFixed(4);
  r.children[3].textContent=(t>=0?' ':'−')+Math.abs(t).toFixed(2);
  r.children[4].textContent=p<0.0005?'0.000':p.toFixed(3);
  r.children[3].className=Math.abs(t)>=1.96?(t>=0?'tqt-ols-summary-sig':'tqt-ols-summary-neg'):'tqt-ols-summary-ins';
  r.children[4].className=p<0.05?'':'tqt-ols-summary-ins';}
 var s2=se(sel),lo=V[sel][1]-1.96*s2,hi=V[sel][1]+1.96*s2;
 ci.innerHTML='<b>'+V[sel][0]+'</b> 95% CI [ '+lo.toFixed(4)+' , '+hi.toFixed(4)+' ] · '+(lo*hi>0?'excludes 0':'straddles 0')+(sel?' · VIF '+VIF[sel].toFixed(2):' · intercept');
 diag.textContent='DW 1.94 · JB 3.12 (p 0.210) · Cond.No 4.7 · resid σ 0.0094 · '+(est?'Newey-West, 6 lags, Bartlett kernel':'errors assumed iid & homoskedastic');}
render();

