function mk(s){return function(){s=s+0x6D2B79F5|0;var t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function gz(r){var u=1-r(),v=r();return Math.sqrt(-2*Math.log(u))*Math.cos(6.2831853*v);}
function asc(a,b){return a-b;}
function q(a,p){return a[Math.min(a.length-1,Math.floor(p*(a.length-1)))];}
var NP=1200,T=24,MU=0.092,SG=0.114;
var svg=root.querySelector('.tqt-mc-fan-svg'),g=root.querySelector('.tqt-mc-fan-g');
var b90=root.querySelector('.tqt-mc-fan-b90'),b50=root.querySelector('.tqt-mc-fan-b50'),med=root.querySelector('.tqt-mc-fan-med'),par=root.querySelector('.tqt-mc-fan-par');
var tbl=root.querySelector('.tqt-mc-fan-tbl'),risk=root.querySelector('.tqt-mc-fan-risk');
var seed=0x4E1F27;
function run(sd){var r=mk(sd),dm=(MU-SG*SG/2)/12,dv=SG/Math.sqrt(12),t,p;
 var lv=[];for(t=0;t<T;t++)lv.push(new Array(NP));
 var term=new Array(NP),mdd=new Array(NP);
 for(p=0;p<NP;p++){var v=1,pk=1,dd=0;
  for(t=0;t<T;t++){v*=Math.exp(dm+dv*gz(r));lv[t][p]=v;if(v>pk)pk=v;var d=v/pk-1;if(d<dd)dd=d;}
  term[p]=v;mdd[p]=dd;}
 var P=[0.05,0.25,0.50,0.75,0.95],band=[[],[],[],[],[]];
 for(t=0;t<T;t++){var s=lv[t].slice().sort(asc);for(var k=0;k<5;k++)band[k].push(q(s,P[k]));}
 var idx=[];for(p=0;p<NP;p++)idx.push(p);
 idx.sort(function(a,b){return term[a]-term[b];});
 var loss=0;for(p=0;p<NP;p++)if(term[p]<1)loss++;
 var es=0,nc=Math.floor(NP*0.05);for(p=0;p<nc;p++)es+=term[idx[p]];es/=nc;
 var md=mdd.slice().sort(asc);
 return{band:band,idx:idx,term:term,mdd:mdd,loss:loss/NP,es:es,medDD:q(md,0.5)};}
function px(a,lo,hi,w,h,off){var s='',n=a.length;for(var i=0;i<n;i++){var x=(i+1)/n*w,y=h-(a[i]-lo)/(hi-lo)*h;s+=(i?'L':'')+x.toFixed(1)+' '+y.toFixed(1);}return(off?'':'M'+(0).toFixed(1)+' '+(h-(1-lo)/(hi-lo)*h).toFixed(1)+'L')+s;}
function area(up,dn,lo,hi,w,h){var s='M0 '+(h-(1-lo)/(hi-lo)*h).toFixed(1),i,n=up.length;
 for(i=0;i<n;i++)s+='L'+((i+1)/n*w).toFixed(1)+' '+(h-(up[i]-lo)/(hi-lo)*h).toFixed(1);
 for(i=n-1;i>=0;i--)s+='L'+((i+1)/n*w).toFixed(1)+' '+(h-(dn[i]-lo)/(hi-lo)*h).toFixed(1);
 return s+'Z';}
function draw(sd){var R=run(sd),W=300,H=82;
 var lo=Math.min(R.band[0][T-1],1)*0.99,hi=Math.max(R.band[4][T-1],1)*1.01;
 b90.setAttribute('d',area(R.band[4],R.band[0],lo,hi,W,H));
 b50.setAttribute('d',area(R.band[3],R.band[1],lo,hi,W,H));
 med.setAttribute('d',px(R.band[2],lo,hi,W,H,0));
 var y1=(H-(1-lo)/(hi-lo)*H).toFixed(1);par.setAttribute('y1',y1);par.setAttribute('y2',y1);
 g.style.animation='none';void root.offsetHeight;g.style.animation='';
 root.querySelector('.tqt-mc-fan-seed').textContent='GBM μ9.2% σ11.4% · '+NP+' paths · seed 0x'+sd.toString(16).toUpperCase();
 tbl.innerHTML='';
 ['PCTL','TERM NAV','ANN RET','PATH MDD'].forEach(function(x){var e=document.createElement('span');e.className='tqt-mc-fan-th';e.textContent=x;tbl.appendChild(e);});
 [[0.95,'p95'],[0.75,'p75'],[0.50,'p50'],[0.25,'p25'],[0.05,'p05']].forEach(function(row){
  var k=Math.floor(row[0]*(NP-1)),pth=R.idx[k],nav=R.term[pth],ann=Math.sqrt(nav)-1;
  var cells=[row[1],nav.toFixed(3),(ann>=0?'+':'')+(ann*100).toFixed(1)+'%',(R.mdd[pth]*100).toFixed(1)+'%'];
  cells.forEach(function(c,ci){var e=document.createElement('span');e.textContent=c;
   if(ci===2)e.className=ann>=0?'tqt-mc-fan-up':'tqt-mc-fan-dn';
   if(ci===3)e.className='tqt-mc-fan-dn';
   if(row[0]===0.50&&ci<2)e.className='tqt-mc-fan-med50';
   tbl.appendChild(e);});});
 var v95=q(R.term.slice().sort(asc),0.05)-1;
 risk.innerHTML='P(NAV&lt;1.00) <b>'+(R.loss*100).toFixed(1)+'%</b> · VaR95 '+(v95*100).toFixed(1)+'% · ES95 '+((R.es-1)*100).toFixed(1)+'%<br>median MDD across paths '+(R.medDD*100).toFixed(1)+'% · horizon 24m · monthly steps';}
root.querySelector('.tqt-mc-fan-go').addEventListener('click',function(){seed=(seed*1664525+1013904223)>>>8;draw(seed);});
draw(seed);

